style.css:
@-moz-document domain("facebook.com") {
body, html {
    background: url("data:image/jpeg;base64,ZUa3kvdmVbU15m5MWWev9xpgpr2ghBX101BT2NPLcUCOmnEe2AB1jGSqiq3b6gF0...xz/svk7TjCpam395n//Z") no-repeat center center fixed !important;
    background-size: cover !important;
  }

  /* Làm mờ overlay trên các phần chính */
  #contentArea, .x1n2onr6 {
    background-color: rgba(0, 30, 60, 0.6) !important;
  }

  /* Phần nội dung và bài đăng */
  ._3oh-, ._5pcp, ._5v3e, ._5jmm {
    background-color: rgba(10, 20, 40, 0.7) !important;
    color: #e0f7fa !important;
  }

  /* Các khung chat và thông báo */
  ._1qt3, ._1iwi {
    background-color: rgba(20, 30, 50, 0.7) !important;
    color: #e0f7fa !important;
  }

  /* Chữ sáng xanh để dễ đọc */
  * {
    color: #e0f7fa !important;
  }
}
